function maximumElementAfterDecrementingAndRearranging(arr) {
  // A maximum of m is reachable exactly when m different elements can stand for 1, 2, ..., m
  // (the rest are lowered to 1 and placed first). By Hall's condition, for every k <= m
  // at least m - k + 1 elements must be >= k.
  const n = arr.length;
  for (let m = n; m >= 1; m--) {
    let fits = true;
    for (let k = 1; k <= m && fits; k++) {
      const big = arr.filter(v => v >= k).length;
      if (big < m - k + 1) fits = false;
    }
    if (fits) return m;
  }
  return 1;
}

