function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const span = [1000, 2500, 1000000000][int(0, 2)];
    return [Array.from({ length: 2000 }, () => int(1, span))];
  }
  const span = [3, 8, 1000000000][int(0, 2)];
  return [Array.from({ length: int(1, 8) }, () => int(1, span))];
}
